import { notFound } from 'next/navigation';
import { DocsLayout } from 'fumadocs-ui/layouts/docs';
import { topicsSource } from '@/lib/source';
import { baseOptions } from '@/lib/layout.shared';
import { DocsNavbar } from '@/components/DocsNavbar';

/**
 * Topics docs shell. Unlike projects (one subtree per project), the
 * whole topics tree is one course catalogue; the sidebar root groups
 * topic folders by primary category (regenerated by build-catalog).
 * Browser pages (/topics, /topics/category/*) live outside this group
 * so they get a full-width shell.
 */
export default async function TopicsDocsLayout({ children }: { children: React.ReactNode }) {
  const tree = topicsSource.getPageTree();
  if (!tree) notFound();
  return (
    <>
      <DocsNavbar className="hidden md:block" />
      <DocsLayout tree={tree} containerProps={{ className: 'docs-with-navbar' }} {...baseOptions()}>
        {children}
      </DocsLayout>
    </>
  );
}
